import{_ as r,C as s,o as e,c as n,a2 as l,b as d,w as o,a as i,E as g,a3 as E}from"./chunks/framework.BBdhqAg0.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",_=JSON.parse('{"title":"문서함 구분 및 다차원 검색 (Approval Boxes)","description":"","frontmatter":{},"headers":[],"relativePath":"approval/boxes.md","filePath":"approval/boxes.md","lastUpdated":1793453038000}'),B={name:"approval/boxes.md"};function C(c,t,x,b,p,h){const a=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="문서함-구분-및-다차원-검색-approval-boxes" tabindex="-1">문서함 구분 및 다차원 검색 (Approval Boxes) <a class="header-anchor" href="#문서함-구분-및-다차원-검색-approval-boxes" aria-label="Permalink to &quot;문서함 구분 및 다차원 검색 (Approval Boxes)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="전자결재 문서함 및 검색 필터 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/boxes.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>IBS 전자결재 문서함</strong>은 사용자의 결재 참여 역할(결재 대기자, 기안자, 결재 완료자, 전사 열람자)에 따라 문서를 체계적으로 분류하며, 다차원 복합 필터링과 다건 일괄 처리를 지원합니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[전자결재 시스템] → [문서함 및 출력] → [문서함 구분 및 검색]**을 선택하여 접속합니다.</li></ul><h2 id="_1-4대-결재-문서함-구성-및-특화-기능" tabindex="-1">1. 4대 결재 문서함 구성 및 특화 기능 <a class="header-anchor" href="#_1-4대-결재-문서함-구성-및-특화-기능" aria-label="Permalink to &quot;1. 4대 결재 문서함 구성 및 특화 기능&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">문서함명</th><th style="text-align:left;">주요 대상 및 기준</th><th style="text-align:left;">전용 기능 및 특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>결재 대기함</strong></td><td style="text-align:left;">내가 현재 결재해야 할 미결 문서<br>(대리 결재 대상 포함)</td><td style="text-align:left;">• 사이드바에 실시간 미결 건수 레드 배지 표시<br>• <strong>다건 일괄 승인 (체크박스 선택 후 원클릭 승인)</strong><br>• 단건 승인/반려 팝업 처리</td></tr><tr><td style="text-align:left;"><strong>기안 문서함</strong></td><td style="text-align:left;">내가 작성한 모든 기안 문서<br>(임시저장, 진행중, 반려, 완료)</td><td style="text-align:left;">• 5가지 상태별 필터링 지원<br>• 임시저장 건 즉시 상신 및 수정/삭제<br>• <strong>1단계 심사 전 기안 회수(취소)</strong><br>• 반려 문서 복사 재기안</td></tr><tr><td style="text-align:left;"><strong>결재 완료함</strong></td><td style="text-align:left;">내가 결재선에 참여하여 최종 승인 완료된 문서</td><td style="text-align:left;">• 결재 참여 이력 및 타임라인 확인<br>• <strong>공식 전자 직인 A4 PDF 다운로드 및 인쇄</strong><br>• 위변조 방지 무결성 검증</td></tr><tr><td style="text-align:left;"><strong>전체 문서함</strong></td><td style="text-align:left;">보안등급 및 열람 권한을 보유한 회사 내 모든 결재 문서</td><td style="text-align:left;">• <strong>7대 다차원 복합 필터링</strong><br>• 전사 결재 현황 모니터링<br>• 페이지네이션 지원</td></tr></tbody></table><h2 id="_2-5대-결재-상태-배지-기준" tabindex="-1">2. 5대 결재 상태 배지 기준 <a class="header-anchor" href="#_2-5대-결재-상태-배지-기준" aria-label="Permalink to &quot;2. 5대 결재 상태 배지 기준&quot;">​</a></h2><p>모든 문서함 목록에서는 문서의 진행 상황을 직관적으로 확인할 수 있도록 색상 배지가 표시됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">상태명</th><th style="text-align:center;">배지 색상</th><th style="text-align:left;">상태 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>임시저장</strong></td><td style="text-align:center;">회색 배지</td><td style="text-align:left;">기안 작성 중인 상태로, 작성자 본인만 조회 및 수정/삭제 가능 (문서번호 미채번)</td></tr><tr><td style="text-align:left;"><strong>결재중</strong></td><td style="text-align:center;">주황색 배지</td><td style="text-align:left;">상신 완료되어 현재 결재 순번의 결재자가 심사 중인 상태</td></tr><tr><td style="text-align:left;"><strong>승인완료</strong></td><td style="text-align:center;">초록색 배지</td><td style="text-align:left;">최종 승인권자까지 결재 완료되어 공식 문서번호 채번 및 PDF 생성된 상태</td></tr><tr><td style="text-align:left;"><strong>반려</strong></td><td style="text-align:center;">빨간색 배지</td><td style="text-align:left;">결재선 중 부적합 판정을 받아 구체적인 사유와 함께 기각된 상태</td></tr><tr><td style="text-align:left;"><strong>취소 (회수)</strong></td><td style="text-align:center;">짙은 회색 배지</td><td style="text-align:left;">1차 결재 승인 전 기안자가 자진 회수하여 중단된 상태</td></tr></tbody></table><h2 id="_3-보안-등급별-열람-범위" tabindex="-1">3. 보안 등급별 열람 범위 <a class="header-anchor" href="#_3-보안-등급별-열람-범위" aria-label="Permalink to &quot;3. 보안 등급별 열람 범위&quot;">​</a></h2><p>전체 문서함 목록 및 검색 시 문서의 보안 등급에 따라 열람 권한이 자동 통제됩니다.</p>',11)),(e(),d(E,null,{default:o(()=>[g(a,{id:"mermaid-168",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%EB%AC%B8%EC%84%9C%20%EB%B3%B4%EC%95%88%20%EB%93%B1%EA%B8%89%22%5D%20--%3E%20B%5B%221%EB%93%B1%EA%B8%89%3A%20%EB%B9%84%EA%B3%B5%EA%B0%9C%3Cbr%3E(Strict)%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%222%EB%93%B1%EA%B8%89%3A%20%EB%B6%80%EC%84%9C%EA%B3%B5%EA%B0%9C%3Cbr%3E(Department)%22%5D%0A%20%20%20%20A%20--%3E%20D%5B%223%EB%93%B1%EA%B8%89%3A%20%EC%A0%84%EC%82%AC%EA%B3%B5%EA%B0%9C%3Cbr%3E(Company)%22%5D%0A%20%20%20%20%0A%20%20%20%20B%20--%3E%20B1%5B%22%EA%B8%B0%EC%95%88%EC%9E%90%20%C2%B7%20%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EC%B0%B8%EC%97%AC%EC%9E%90%20%C2%B7%20%EC%A7%80%EC%A0%95%20%EC%B0%B8%EC%A1%B0%EC%9E%90%EB%A7%8C%20%EC%97%B4%EB%9E%8C%22%5D%0A%20%20%20%20C%20--%3E%20C1%5B%22%EA%B8%B0%EC%95%88%EC%9E%90%20%EC%86%8C%EC%86%8D%20%EB%B6%80%EC%84%9C%EC%9B%90%20%EC%A0%84%EC%B2%B4%20%EC%97%B4%EB%9E%8C%20(%EA%B8%B0%EB%B3%B8%20%EA%B6%8C%EC%9E%A5)%22%5D%0A%20%20%20%20D%20--%3E%20D1%5B%22%ED%9A%8C%EC%82%AC%20%EC%A0%84%EC%B2%B4%20%EC%9E%84%EC%A7%81%EC%9B%90%20%EC%97%B4%EB%9E%8C%20%EA%B0%80%EB%8A%A5%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_4-다차원-복합-검색-및-필터링" tabindex="-1">4. 다차원 복합 검색 및 필터링 <a class="header-anchor" href="#_4-다차원-복합-검색-및-필터링" aria-label="Permalink to &quot;4. 다차원 복합 검색 및 필터링&quot;">​</a></h2><p><strong>전체 문서함</strong> 및 각 목록 상단에는 대량의 문서 중에서 필요한 결재 건을 신속하게 찾을 수 있는 7대 필터 툴바가 제공됩니다:</p><ul><li><strong>카테고리 필터</strong>: <code>일반/공통</code>, <code>인사/근태</code>, <code>회계/자금</code>, <code>계약/법무</code>, <code>사업/프로젝트</code> 등 대분류 선택</li><li><strong>문서 유형 필터</strong>: 카테고리 선택 시 해당 분류에 속한 세부 양식(예: <code>휴가신청서</code>, <code>지출결의서</code>)만 동적 필터링</li><li><strong>진행 상태 필터</strong>: <code>결재중</code>, <code>승인완료</code>, <code>반려</code>, <code>임시저장</code>, <code>취소</code> 단일 선택</li><li><strong>보안 등급 필터</strong>: <code>1등급 (비공개)</code>, <code>2등급 (부서공개)</code>, <code>3등급 (전사공개)</code></li><li><strong>소속 부서 필터</strong>: 특정 부서에서 기안된 문서만 지정 조회 (전체 문서함 전용)</li><li><strong>기간 검색</strong>: 달력 선택기를 통해 기안일자 기준 시작일 ~ 종료일 범위 지정</li><li><strong>키워드 통합 검색</strong>: 문서 번호, 기안자 이름, 문서 제목을 포괄하는 실시간 텍스트 검색</li></ul><h2 id="_5-신입사원을-위한-문서함-활용-팁" tabindex="-1">5. 신입사원을 위한 문서함 활용 팁 <a class="header-anchor" href="#_5-신입사원을-위한-문서함-활용-팁" aria-label="Permalink to &quot;5. 신입사원을 위한 문서함 활용 팁&quot;">​</a></h2><ul><li><strong>내가 올린 문서가 결재되었는지 확인하려면</strong>: **[기안 문서함]**으로 이동하세요. 현재 누가 결재할 차례인지 주황색 배지와 결재선 타임라인에서 바로 확인할 수 있습니다.</li><li><strong>내가 결재해야 할 문서가 있다면</strong>: 시스템 좌측 메뉴의 <strong>[결재 대기함]</strong> 옆에 빨간색 숫자 배지가 뜹니다. 배지가 보이면 즉시 클릭하여 결재를 검토해 주세요.</li></ul>',5))])}const y=r(B,[["render",C]]);export{_ as __pageData,y as default};
